{"content":"def encode(numbers):
    """Encode unsigned 32-bit integers as a flat list of VLQ bytes."""
    encoded = []
    for number in numbers:
        if not 0 <= number <= 0xFFFFFFFF:
            raise ValueError("number must be an unsigned 32-bit integer")

        groups = [number & 0x7F]
        number >>= 7
        while number:
            groups.append((number & 0x7F) | 0x80)
            number >>= 7
        encoded.extend(reversed(groups))
    return encoded


def decode(bytes_):
    """Decode VLQ bytes, rejecting unfinished or out-of-range values."""
    decoded = []
    number = 0
    incomplete = False
    for byte in bytes_:
        if not 0 <= byte <= 0xFF:
            raise ValueError("byte must be between 0 and 255")

        number = (number << 7) | (byte & 0x7F)
        if number > 0xFFFFFFFF:
            raise ValueError("decoded number exceeds unsigned 32-bit range")
        incomplete = bool(byte & 0x80)
        if not incomplete:
            decoded.append(number)
            number = 0

    if incomplete:
        raise ValueError("incomplete sequence")
    return decoded
